<script setup lang="ts">
import { formatCalgaryTime } from '~/utils/time'
const { data } = await useFetch('/api/weather')
const clock = ref('Loading…'); let timer: ReturnType<typeof setInterval>
onMounted(() => { const update=()=>clock.value=formatCalgaryTime(new Date()); update(); timer=setInterval(update,500) }); onUnmounted(()=>clearInterval(timer))
</script>
